const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(125.93, -20.59);
    const date = '2020-01-14';

    // Himawari-8 data is in UTC.
    // Western Australia (AWST) is UTC+8.
    // 11:00 AWST = 03:00 UTC
    // 14:00 AWST = 06:00 UTC

    const startUtc = ee.Date(date).advance(3, 'hour'); // 11:00 AWST = 03:00 UTC
    const endUtc = ee.Date(date).advance(6, 'hour');   // 14:00 AWST = 06:00 UTC

    // Define two time windows for comparison:
    // Window 1: 11:00 - 12:30 AWST (03:00 - 04:30 UTC)
    // Window 2: 12:30 - 14:00 AWST (04:30 - 06:00 UTC)
    const window1StartUtc = startUtc;
    const window1EndUtc = ee.Date(date).advance(4, 'hour').advance(30, 'minute'); // 04:30 UTC
    const window2StartUtc = ee.Date(date).advance(4, 'hour').advance(30, 'minute'); // 04:30 UTC
    const window2EndUtc = endUtc;

    const scale = 5000; // Use a larger scale for faster computation and stability

    // 2. Data Acquisition & Pre-processing
    // Use Himawari-8 AHI Cloud product for intra-day cloud cover analysis
    let himawari = ee.ImageCollection('NOAA/Himawari/H8/AHI/v5')
      .filterBounds(point)
      .filterDate(startUtc, endUtc);

    // Check for empty collection
    if (himawari.size().getInfo() === 0) {
      console.log("C1: No Himawari-8 images found for the specified date and location.");
      return;
    }

    // Function to calculate cloud percentage for a given collection subset
    const calculateCloudPercentage = (collection, windowName) => {
      const images = collection.map(image => {
        // The 'cloud_mask' band has values: 0=clear, 1=cloudy, 2=probably cloudy, 3=clear_sky_over_water.
        // We consider 1 (cloudy) or 2 (probably cloudy) as cloudy.
        // Create a binary cloud mask: 1 for cloudy, 0 for clear.
        const cloudPixels = image.select('cloud_mask').eq(1).or(image.select('cloud_mask').eq(2));
        return cloudPixels.rename('cloudy');
      });

      if (images.size().getInfo() === 0) {
        console.log(`C1: No images found for ${windowName}.`);
        return null;
      }

      // Mosaic images in the window and reduce
      const mosaicedImage = images.mosaic();
      const stats = mosaicedImage.reduceRegion({
        reducer: ee.Reducer.count().addReducer(ee.Reducer.sum()),
        geometry: point,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();

      const totalPixels = stats ? stats['cloudy_count'] : 0;
      const cloudyPixels = stats ? stats['cloudy_sum'] : 0;

      if (totalPixels === 0) {
        console.log(`C2: No valid pixels for ${windowName} after processing.`);
        return null;
      }

      const cloudPercentage = (cloudyPixels / totalPixels) * 100;
      return { count: collection.size().getInfo(), totalPixels: totalPixels, cloudyPixels: cloudyPixels, percentage: cloudPercentage };
    };

    // Filter for Window 1 (11:00 - 12:30 AWST)
    const window1Collection = himawari.filterDate(window1StartUtc, window1EndUtc);
    const window1Stats = calculateCloudPercentage(window1Collection, 'Window 1 (11:00-12:30 AWST)');

    // Filter for Window 2 (12:30 - 14:00 AWST)
    const window2Collection = himawari.filterDate(window2StartUtc, window2EndUtc);
    const window2Stats = calculateCloudPercentage(window2Collection, 'Window 2 (12:30-14:00 AWST)');

    if (window1Stats === null || window2Stats === null) {
      console.log("C3: Could not compute cloud percentage for one or both windows.");
      return;
    }

    // 3. Calculation & Comparison
    const cloud1 = window1Stats.percentage;
    const cloud2 = window2Stats.percentage;

    if (cloud1 === null || cloud2 === null) {
      console.log("C3: Cloud percentage calculation resulted in null/NaN.");
      return;
    }

    console.log(`Window 1 (11:00-12:30 AWST) - Images: ${window1Stats.count}, Cloud %: ${cloud1.toFixed(2)}`);
    console.log(`Window 2 (12:30-14:00 AWST) - Images: ${window2Stats.count}, Cloud %: ${cloud2.toFixed(2)}`);

    // 4. Validation & Final Answer
    if (cloud2 > cloud1) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("D: An error occurred during the analysis:", e);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
